    public void record(@Val ReopenedPeriod reopened, @Val ChangedBy by, Audit audit) {
        Period period = reopened.period();
        audit.record("PERIOD_REOPENED sheet=" + period.sheetId() + " by=" + by.name() + " period=" + period.name());
    }
}
