package net.officefloor.hq.app.period;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.access.Role;
import net.officefloor.hq.app.access.RoleRepository;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * ${kind}s the period$( [ $kind = Lock ] && echo ", so it cannot be reopened until unlocked" ); only a steward may, and a period ${state} is refused.
 */
public class ${kind}Period {
    public void ${verb}(@Val Period period, @Val ChangedBy by, PeriodRepository repository, RoleRepository roles,
            Out<LockedPeriod> ${past}) throws BadRequestException {
        if (!Role.STEWARD.equals(roles.roleOf(period.sheetId(), by.name()))) {
            throw new BadRequestException("Only a steward may ${verb} a period");
        }
        if (period.locked() == ${want} || !repository.setLocked(period.id(), ${want})) {
            throw new BadRequestException("That period is ${state}");
        }
        ${past}.set(new LockedPeriod(new Period(period.id(), period.sheetId(), period.name(), period.from(), period.to(),
                period.closed(), period.closedTotal(), period.personTotals(), period.soft(), period.cap(),
                period.personCarried(), ${want})));
    }
}
EOF
