import net.officefloor.plugin.variable.Val;

public class RecordPeriod${kind}ed {
    public void record(@Val LockedPeriod ${past}, @Val ChangedBy by, Audit audit) {
        Period period = ${past}.period();
        audit.record("${EV} sheet=" + period.sheetId() + " by=" + by.name() + " period=" + period.name());
